require_once __DIR__.'/../auth/auth.php';require_once __DIR__.'/../database/db.php';require_once __DIR__.'/../helpers/helpers.php';require_once __DIR__.'/../helpers/stuff.php';$current_page='account';$account_tab='overview';require_login();if(is_admin()){header('Location: '.ADMIN_URL.'admin.php');exit;}
$uid=current_user_id();$q=$conn->prepare('SELECT COUNT(*) FROM orders WHERE user_id=?');$q->execute([$uid]);$orders=(int)$q->fetchColumn();$q=$conn->prepare("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE user_id=? AND status='completed'");$q->execute([$uid]);$spent=(float)$q->fetchColumn();$cart=get_cart_count($conn,$uid);$q=$conn->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC LIMIT 5');$q->execute([$uid]);$recent=$q->fetchAll();require __DIR__.'/../includes/header.php';?>
<section class="dashboard-shell"><div class="container"><div class="dashboard-heading"><div><p class="tech-label">// OPERATOR_ACCOUNT</p><h1 class="section-heading">WELCOME, <?php echo strtoupper(safe_output(current_user_name()));?></h1></div></div><?php require __DIR__.'/../includes/account-nav.php';?><div class="metric-grid metric-grid-three"><article class="metric-card"><span>YOUR ORDERS</span><strong><?php echo $orders;?></strong><small>All transactions</small></article><article class="metric-card"><span>TOTAL SPENT</span><strong><?php echo format_price($spent);?></strong><small>Completed orders</small></article><article class="metric-card"><span>CART ITEMS</span><strong><?php echo $cart;?></strong><small>Ready for checkout</small></article></div><section class="dashboard-panel"><div class="panel-heading"><div><span>RECENT_ORDERS // 01</span><h2>YOUR ACTIVITY</h2></div><a class="text-link compact-link" href="orders.php">VIEW ALL →</a></div><div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>ORDER</th><th>AMOUNT</th><th>STATUS</th><th>DATE</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="4">You have not placed an order yet.</td></tr><?php else:foreach($recent as $o):?><tr><td>#<?php echo str_pad($o['id'],4,'0',STR_PAD_LEFT);?></td><td><?php echo format_price($o['total_amount']);?></td><td><span class="status-badge status-<?php echo safe_output($o['status']);?>"><?php echo strtoupper(safe_output($o['status']));?></span></td><td><?php echo date('M d, Y',strtotime($o['created_at']));?></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></section><?php require __DIR__.'/../includes/footer.php';?>
